INSERT INTO _migration_464_expected (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_wisc_acids_b002_001', 'topic_wassce_intsci_acids', 'subj_wassce_int_science', 'exam_wassce', NULL, NULL, 'Blue litmus paper dipped into dilute hydrochloric acid turns', 'multiple_choice', NULL, '["A. white","B. green","C. red","D. deeper blue"]', 'C', 'Acids turn blue litmus paper red, and hydrochloric acid is a strong acid, so the paper turns red at once; it does not bleach to white, turn green or remain blue, which is the colour litmus keeps in neutral or alkaline solutions. Therefore the correct answer is C: red.', 'easy', '3', '1', '45', NULL, NULL, '1', NULL, NULL, 'Identify', 'AO2', NULL, NULL, NULL),
('q_wisc_acids_b002_002', 'topic_wassce_intsci_acids', 'subj_wassce_int_science', 'exam_wassce', NULL, NULL, 'When dilute hydrochloric acid reacts completely with sodium hydroxide solution, the products are', 'multiple_choice', NULL, '["A. sodium chloride and hydrogen gas","B. hydrogen gas and oxygen gas","C. sodium metal and chlorine gas","D. sodium chloride and water"]', 'D', 'An acid plus a base gives a salt and water: HCl + NaOH produce NaCl + H2O. This neutralisation does not release hydrogen or oxygen gases, and it certainly cannot produce free sodium metal or chlorine gas from aqueous solution. Therefore the correct answer is D: sodium chloride and water.', 'medium', '3', '1', '45', NULL, NULL, '1', NULL, NULL, 'Identify', 'AO2', NULL, NULL, NULL),
('q_wisc_acids_b002_003', 'topic_wassce_intsci_acids', 'subj_wassce_int_science', 'exam_wassce', NULL, NULL, 'Dilute hydrochloric acid is added to zinc granules. The gas evolved and its correct test are', 'multiple_choice', NULL, '["A. hydrogen, which gives a pop sound with a lighted splint","B. oxygen, which relights a glowing splint","C. carbon dioxide, which turns limewater milky","D. chlorine, which bleaches damp litmus paper"]', 'A', 'Zinc + hydrochloric acid give zinc chloride and hydrogen: Zn + 2HCl produce ZnCl2 + H2. Hydrogen burns with a pop at a lighted splint; the glowing-splint, limewater and bleaching tests belong to oxygen, carbon dioxide and chlorine respectively. Therefore the correct answer is A: hydrogen, which gives a pop sound with a lighted splint.', 'medium', '3', '1', '45', NULL, NULL, '1', NULL, NULL, 'Identify', 'AO2', NULL, NULL, NULL),
('q_wisc_acids_b002_004', 'topic_wassce_intsci_acids', 'subj_wassce_int_science', 'exam_wassce', NULL, NULL, 'Which of the following is a weak acid commonly found in the kitchen?', 'multiple_choice', NULL, '["A. Hydrochloric acid","B. Ethanoic acid in vinegar","C. Sodium hydroxide","D. Sodium chloride"]', 'B', 'Vinegar is a dilute solution of ethanoic acid, which ionises only partially in water and is therefore a weak acid. Hydrochloric acid is a strong mineral acid, sodium hydroxide is a base, and sodium chloride is a neutral salt. Therefore the correct answer is B: Ethanoic acid in vinegar.', 'medium', '3', '1', '45', NULL, NULL, '1', NULL, NULL, 'Identify', 'AO2', NULL, NULL, NULL),
('q_wisc_acids_b002_005', 'topic_wassce_intsci_acids', 'subj_wassce_int_science', 'exam_wassce', NULL, NULL, 'The difference between a strong acid and a concentrated acid is that', 'multiple_choice', NULL, '["A. the two terms always mean exactly the same thing","B. a strong acid is one that contains more water","C. strength describes the degree of ionisation while concentration describes the amount of acid per unit volume","D. a concentrated acid is always fully ionised"]', 'C', 'Strength is about how completely the acid ionises: hydrochloric acid is strong even when very dilute because it ionises fully. Concentration is about moles per unit volume: ethanoic acid can be highly concentrated yet weak because only a small fraction of its molecules ionise. Therefore the correct answer is C: strength describes the degree of ionisation while concentration describes the amount of acid per unit volume.', 'hard', '3', '1', '45', NULL, NULL, '1', NULL, NULL, 'Distinguish', 'AO3', NULL, NULL, NULL),
('q_wisc_acids_b002_006', 'topic_wassce_intsci_acids', 'subj_wassce_int_science', 'exam_wassce', NULL, NULL, 'Which of the following salts forms an acidic solution when dissolved in water?', 'multiple_choice', NULL, '["A. Sodium chloride","B. Sodium carbonate","C. Potassium nitrate","D. Ammonium chloride"]', 'D', 'Ammonium chloride is the salt of a weak base (ammonia) and a strong acid (hydrochloric acid); the ammonium ion hydrolyses in water to release hydroxonium ions, so the solution is acidic. Sodium chloride and potassium nitrate give neutral solutions, while sodium carbonate solution is alkaline. Therefore the correct answer is D: Ammonium chloride.', 'hard', '3', '1', '45', NULL, NULL, '1', NULL, NULL, 'Apply', 'AO3', NULL, NULL, NULL),
('q_wisc_acids_b002_007', 'topic_wassce_intsci_acids', 'subj_wassce_int_science', 'exam_wassce', NULL, NULL, 'In a titration, 25.0 cubic centimetres of 0.10 mol per cubic decimetre hydrochloric acid exactly neutralise 20.0 cubic centimetres of sodium hydroxide solution. Calculate the concentration of the sodium hydroxide solution in mol per cubic decimetre.', 'calculation', NULL, NULL, '0.125 mol per cubic decimetre', 'Moles of HCl = concentration x volume = 0.10 x 25.0/1000 = 0.0025 mol. The equation HCl + NaOH produce NaCl + H2O shows a 1:1 mole ratio, so moles of NaOH = 0.0025 mol. Concentration of NaOH = moles / volume = 0.0025 / (20.0/1000) = 0.0025 / 0.020 = 0.125 mol per cubic decimetre.', 'hard', '4', '2', '120', NULL, NULL, '1', NULL, NULL, 'Calculate', 'AO2', NULL, NULL, NULL),
('q_wisc_acids_b002_008', 'topic_wassce_intsci_acids', 'subj_wassce_int_science', 'exam_wassce', NULL, NULL, 'Calculate the mass of sodium hydroxide, NaOH, needed to prepare 500 cubic centimetres of a 0.20 mol per cubic decimetre solution. (Relative atomic masses: Na = 23, O = 16, H = 1)', 'calculation', NULL, NULL, '4.0 g', 'Moles of NaOH = concentration x volume = 0.20 x 500/1000 = 0.20 x 0.5 = 0.10 mol. Molar mass of NaOH = 23 + 16 + 1 = 40 g per mol. Mass = moles x molar mass = 0.10 x 40 = 4.0 g.', 'medium', '4', '2', '120', NULL, NULL, '1', NULL, NULL, 'Calculate', 'AO2', NULL, NULL, NULL);
INSERT INTO _migration_464_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM _migration_464_expected e JOIN questions q ON q.id = e.id WHERE NOT (q.topic_id IS e.topic_id AND q.subject_id IS e.subject_id AND q.exam_type_id IS e.exam_type_id AND q.paper_type_id IS e.paper_type_id AND q.past_paper_id IS e.past_paper_id AND q.question_text IS e.question_text AND q.question_type IS e.question_type AND q.round_type IS e.round_type AND q.options IS e.options AND q.correct_answer IS e.correct_answer AND q.explanation IS e.explanation AND q.difficulty IS e.difficulty AND q.points IS e.points AND q.marks IS e.marks AND q.time_limit IS e.time_limit AND q.question_number IS e.question_number AND q.section IS e.section AND q.is_compulsory IS e.is_compulsory AND q.image_url IS e.image_url AND q.syllabus_topic_id IS e.syllabus_topic_id AND q.command_word IS e.command_word AND q.assessment_objective IS e.assessment_objective AND q.source_paper_code IS e.source_paper_code AND q.source_question_number IS e.source_question_number AND q.exam_board_id IS e.exam_board_id)) AND NOT EXISTS (SELECT 1 FROM _migration_464_expected e JOIN question_content_releases r ON r.question_id = e.id WHERE NOT (r.batch_id IS 'wassce-int-science-sprint2-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Integrated Science practice; not official WAEC examination material.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) SELECT id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id FROM _migration_464_expected e WHERE NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = e.id);
INSERT INTO question_content_releases (question_id, batch_id, quality_assurance, release_channel, content_label, source_url, official_exam_board_content, feedback_enabled) SELECT e.id, 'wassce-int-science-sprint2-001', 'automated_beta', 'beta', 'Original BrillaPrep curriculum-aligned WASSCE Integrated Science practice; not official WAEC examination material.', 'https://nacca.gov.gh/secondary-education-curriculum/', 0, 1 FROM _migration_464_expected e WHERE NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = e.id);
INSERT INTO _migration_464_guard(valid) SELECT CASE WHEN (SELECT COUNT(*) FROM questions q JOIN _migration_464_expected e ON e.id = q.id AND q.topic_id IS e.topic_id AND q.subject_id IS e.subject_id AND q.exam_type_id IS e.exam_type_id AND q.paper_type_id IS e.paper_type_id AND q.past_paper_id IS e.past_paper_id AND q.question_text IS e.question_text AND q.question_type IS e.question_type AND q.round_type IS e.round_type AND q.options IS e.options AND q.correct_answer IS e.correct_answer AND q.explanation IS e.explanation AND q.difficulty IS e.difficulty AND q.points IS e.points AND q.marks IS e.marks AND q.time_limit IS e.time_limit AND q.question_number IS e.question_number AND q.section IS e.section AND q.is_compulsory IS e.is_compulsory AND q.image_url IS e.image_url AND q.syllabus_topic_id IS e.syllabus_topic_id AND q.command_word IS e.command_word AND q.assessment_objective IS e.assessment_objective AND q.source_paper_code IS e.source_paper_code AND q.source_question_number IS e.source_question_number AND q.exam_board_id IS e.exam_board_id) = 8 AND (SELECT COUNT(*) FROM question_content_releases r JOIN _migration_464_expected e ON e.id = r.question_id WHERE r.batch_id IS 'wassce-int-science-sprint2-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Integrated Science practice; not official WAEC examination material.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1) = 8 AND (SELECT COUNT(*) FROM questions q JOIN topics t ON t.id = q.topic_id AND t.subject_id = q.subject_id JOIN _migration_464_expected e ON e.id = q.id) = 8 AND (SELECT COUNT(*) FROM structured_question_parts sp JOIN _migration_464_expected_parts p ON p.id = sp.id AND sp.id IS p.id AND sp.question_id IS p.question_id AND sp.part_label IS p.part_label AND sp.part_text IS p.part_text AND sp.marks IS p.marks AND sp.correct_answer IS p.correct_answer AND sp.display_order IS p.display_order) = 0 THEN 1 ELSE 0 END;
